{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Add pairwise ranking supervision on the existing sampled pairs at valid positions. Preserve the weighted BCE objective and all model, sampling, training, and inference settings across all four datasets.",
      "edits": [
        {
          "find": "            loss = ((pos_loss + neg_loss) * weights).sum() / weights.sum().clamp_min(1e-8)",
          "replace": "            loss = ((pos_loss + neg_loss) * weights).sum() / weights.sum().clamp_min(1e-8)\n            pairwise_loss = nn.functional.softplus(\n                neg_logits[indices] - pos_logits[indices]\n            ).mean()\n            loss = loss + 0.2 * pairwise_loss"
        }
      ]
    }
  ],
  "change_summary": "Retain weighted BCE and add 0.2 times mean pairwise softplus loss. Architecture, checkpoints, and predictor remain compatible."
}
